"""Regenerate the embedded client schema from the canonical local JSON schema."""
import json
from pathlib import Path
root = Path(__file__).resolve().parents[1]
schema = json.loads((root / 'doc/telemetry/schema_v1.json').read_text())
license = (root / 'doc/telemetry/cpp_license.txt').read_text().format(name='sltelemetryschema.h')
(root / 'indra/newview/sltelemetryschema.h').write_text(license + '// Generated by telemetry_server/generate_schema.py; do not edit.\n#pragma once\nnamespace SLTelemetry { inline constexpr char SCHEMA_JSON[] = R"sljson(' + json.dumps(schema, separators=(',', ':')) + ')sljson"; }\n')

settings = schema['properties']['settings']['properties']
header = (root / 'doc/telemetry/cpp_license.txt').read_text().format(name='sltelemetrysettings.h')
header += '// Closed numeric/boolean settings; generated from the canonical schema.\n#pragma once\n#include <array>\nnamespace SLTelemetry {\nstruct SettingRule { const char* name; unsigned type; double lower, upper, step; std::array<unsigned,16> buckets; unsigned bucketCount; };\ninline constexpr SettingRule SETTING_RULES[] = {\n'
for name, rule in settings.items():
    kind = {'boolean':0, 'integer':1, 'number':2}[rule['type']]
    buckets = rule.get('enum', [])
    assert len(buckets) <= 16
    header += '    {"'+name+'",'+str(kind)+','+str(rule.get('minimum',0))+','+str(rule.get('maximum',1))+','+str(rule.get('multipleOf',1))+', {'+','.join(map(str,buckets))+'},'+str(len(buckets))+'},\n'
header += '};\ninline constexpr unsigned SETTING_COUNT = sizeof(SETTING_RULES)/sizeof(SETTING_RULES[0]);\n}\n'
(root / 'indra/newview/sltelemetrysettings.h').write_text(header)

import html
rows=[]
def guide(rule,path=''):
    kind=rule['type']
    if kind=='object':
        for name,child in rule['properties'].items(): guide(child,(path+'.' if path else '')+name)
        return
    detail=[]
    if 'enum' in rule: detail.append('Allowed: '+', '.join(map(str,rule['enum'])))
    if 'minimum' in rule: detail.append('Range: '+str(rule['minimum'])+' to '+str(rule['maximum']))
    if 'multipleOf' in rule: detail.append('Step: '+str(rule['multipleOf']))
    if 'pattern' in rule: detail.append('Full-match grammar: '+rule['pattern'])
    if 'maxLength' in rule: detail.append('Maximum length: '+str(rule['maxLength']))
    if kind=='array': detail.append('Array length '+str(rule['minItems'])+' to '+str(rule['maxItems']))
    rows.append('<tr><td><code>'+html.escape(path)+'</code></td><td>'+html.escape(kind)+'</td><td>'+html.escape('; '.join(detail))+'</td></tr>')
guide(schema)
page='<!doctype html><html lang="en"><meta charset="utf-8"><title>Usage statistics field guide</title><style>body{font:16px system-ui;max-width:1100px;margin:2rem auto;padding:1rem}td,th{padding:.5rem;text-align:left;border-bottom:1px solid #ccc}code{overflow-wrap:anywhere}</style><h1>Usage statistics field guide</h1><p>Generated from schema_v1.json. Only these typed fields are accepted. Unknown fields are rejected at every nesting level. See implementation.md for units, unsupported measurements and backport details; privacy.md is the publication draft.</p><p>The preview displays a literal serialized snapshot. A queued preview is the exact body handed to the sender; an unfrozen live snapshot can change as the window grows. Last sent retains the exact successfully posted bytes in memory only. An off-state preview is a user-initiated one-shot and is neither saved nor sent.</p><p>Count gauges use log2 bucket indices: 0 means zero, 1 means 1, 2 means 2–3, 3 means 4–7, continuing through 32. Histograms have 66 bins: below 1 ms, 64 logarithmic bins through 2000 ms, and overflow. Percentiles use approximate bin midpoints. Durations are coarse buckets, not client timestamps. Similar hardware profiles may correlate reports; there is no account or installation identifier.</p><table><tr><th>Field</th><th>Type</th><th>Constraints</th></tr>'+''.join(rows)+'</table></html>\n'
(root/'doc/telemetry/field-guide.html').write_text(page)
